import numpy as np, torch, model
net=model.load()
xi=np.load('my5_xi.npy')[:3000]; c=np.load('my5_c.npy')[:3000]
w=torch.tensor(np.load('contrast_c5_blocks.2.act_k8.npy')); b=-28.0966
r0=model.decode(net,xi,c); a0=np.asarray(r0[0] if isinstance(r0,tuple) else r0)
ANG=lambda a: np.degrees(np.arctan2(a[:,1],a[:,0]))
def tgt(a): g=ANG(a); return (g>-120)&(g<-70)
def c0(a): g=ANG(a); return (g>-140)&(g<-115)
bins=np.arange(-180,181,15)
def hist(a):
    m=~tgt(a)&~c0(a); h,_=np.histogram(ANG(a)[m],bins=bins); return h/len(a)
h0=hist(a0); T0=tgt(a0).mean(); C0=c0(a0).mean()
state={}
def h_act(m,i,o): state['s']=(o@w+b)
def run(M,bb,KHI=9):
    M=torch.tensor(M,dtype=torch.float32); bb=torch.tensor(bb,dtype=torch.float32)
    cnt={'k':0}
    def h_out(m,i,o):
        k=cnt['k']; cnt['k']+=1
        if k<KHI:
            f=(state['s']>0).float().unsqueeze(-1)
            return o+f*(state['x']@M.T+bb)
        return o
    def h_in(m,i): state['x']=i[0]
    h0_=net.inp.register_forward_pre_hook(h_in)
    h1=net.blocks[2].act.register_forward_hook(h_act); h2=net.out.register_forward_hook(h_out)
    r=model.decode(net,xi,c); h0_.remove(); h1.remove(); h2.remove()
    return np.asarray(r[0] if isinstance(r,tuple) else r)
rng=np.random.default_rng(1); res=[]
cands=[(np.zeros((2,2)),np.array([6.,0])),(np.zeros((2,2)),np.array([-6.,0])),(np.zeros((2,2)),np.array([-6.,-3]))]
for s in [3,6,10]:
    cands+= [(s*np.array([[0,-1],[1,0.]]),np.zeros(2)),(s*np.array([[0,1],[-1,0.]]),np.zeros(2)),(s*np.eye(2),np.zeros(2)),(-s*np.eye(2),np.zeros(2)),(s*np.array([[1,0],[0,-1.]]),np.zeros(2)),(s*np.array([[-1,0],[0,1.]]),np.zeros(2))]
for _ in range(10): cands.append((rng.normal(0,5,(2,2)),rng.normal(0,3,2)))
for j,(M,bb) in enumerate(cands):
    a=run(M,bb); fall=T0-tgt(a).mean(); dc0=c0(a).mean()-C0
    h=hist(a); tv=0.5*np.abs(h/h.sum()-h0/h0.sum()).sum()
    res.append((j,fall,dc0,tv)); print(j,np.round(M,1).tolist(),np.round(bb,1).tolist(),'fall %.3f dc0 %.3f tv %.3f'%(fall,dc0,tv))
np.save('cands_M.npy',np.array([m for m,_ in cands],np.float32)); np.save('cands_b.npy',np.array([q for _,q in cands],np.float32))
